class CalculatingProcessVariable(InstrumentationActivity):
    """This InstrumentationActivity calculates an output that is some mathematical function of the inputs. This is a parent type for specialized calculations with specific purposes."""

    uri: ClassVar[str] = "https://pyDEXPI.org/schemas/pydexpi_2_0/CalculatingProcessVariable"


class CalculatingRatio(CalculatingProcessVariable):
    """This CalculatingProcessVariable process calculates an output signal that is the ratio of the two input signals. It can be used to specify and design ratio control functions.  If the two input signals are Dividend and Divisor, then OutputValue = Gain * Dividend/Divisor + Offset ."""

    uri: ClassVar[str] = "https://pyDEXPI.org/schemas/pydexpi_2_0/CalculatingRatio"

    # Compositional attributes
    gain: list[QualifiedValue] = Field(
        default_factory=list,
        description="Multiplier in the ratio calculation.",
        json_schema_extra={
            "attribute_category": "composition",
            "value_types": ["float", "Undefined"],
        },
    )
    offset: list[QualifiedValue] = Field(
        default_factory=list,
        description="Offset added to the ratio calculation.",
        json_schema_extra={
            "attribute_category": "composition",
            "value_types": ["float", "Undefined"],
        },
    )
    outputValue: list[QualifiedValue] = Field(
        default_factory=list,
        description="The calculated ratio.",
        json_schema_extra={
            "attribute_category": "composition",
            "value_types": ["float", "Undefined"],
        },
    )


